dRep.statement:
def dRep : Representation ℤ_[l] (G k Ω) (Dinf l N U) :=
  (funRep ℤ_[l] (QZ l) (cycU l U)).subrepresentation (Dinf l N U) fun g _ h =>
    (funRepMem k Ω N (cycU l U) ℤ_[l] (QZ l)).1 g _ h

dtVal.statement:
private theorem dt_val_lt_one {Ω Ω' : Type} [Field Ω] [Field Ω'] {σ : Ω ≃+* Ω'} {A : ValuationSubring Ω}
    {A' : ValuationSubring Ω'} (hA : ∀ x, x ∈ A ↔ σ x ∈ A') (x : Ω) :
    A.valuation x < 1 ↔ A'.valuation (σ x) < 1

qzTw.statement:
def qzTw (D : LData F Ω l) (e : ℤ) :
    Representation ℤ_[l] (GS Ω (D.S : Set (HeightOneSpectrum (𝓞 F)))) (QZ l) :=
  scalRep (QZ l) (D.chi ^ (-e))

cycZ.statement:
def cycZ (l : ℕ) [Fact l.Prime] : G F Ω →* ℤ_[l]ˣ :=
  (cyclotomicCharacter (Ω) l).comp
    (MulSemiringAction.toRingAut (G F Ω) (Ω))
